INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000000189', 'radical', '令', 'orders', 11, 0, 'Stempel "Topi-Tanah" ada di amplop ini. Itu hanya berarti satu hal: Perintah dari Kantor Pusat. Bayangkan stempel ini pada beberapa pesanan untuk Anda—bacalah pesanan tersebut dengan lantang untuk membantu Anda mengingat bahwa stempel bertopi ini berarti "pesanan" dan tidak ada yang lain.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000190', 'radical', '申', 'humble', 11, 1, 'Radikal ini sama dengan kanji yang Anda pelajari sebelumnya, namun maknanya sedikit berbeda. Ini bukan hanya tentang mengatakan sesuatu dengan rendah hati, tapi juga tentang bersikap rendah hati secara umum. Ketika Anda melihat hal radikal ini, pikirkanlah untuk bersikap rendah hati.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000191', 'radical', '兄', 'older-brother', 11, 2, 'Radikal ini sama dengan kanji. Artinya kakak laki-laki.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000193', 'radical', '及', 'escalator', 11, 3, 'Apakah Anda ingat tangga (乃)? Radikal ini hampir sama, tetapi ada bagian-bagiannya yang ekstra. Itu masih tangga... tapi lebih rumit. Dan lebih cepat! Itu sebabnya ini adalah eskalator!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000194', 'radical', '戈', 'drunkard', 11, 4, 'Ini adalah upacara radikal dengan slide radikal. Mengapa seseorang meluncur di lantai pada sebuah upacara? Jika mereka pemabuk, itu alasannya! Orang suka minum pada upacara. Dan selalu ada setidaknya satu pemabuk yang bertindak terlalu jauh dan tergelincir ke lantai sambil melakukan cacingan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000195', 'radical', '皮', 'skin', 11, 5, 'Radikal ini sama dengan kanji. Artinya kulit.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000196', 'radical', '艮', 'root', 11, 6, 'Jika matahari terbit dan Anda menginjak tanah, Anda akan mencapai <radikal>akar</radikal>. Akar mencoba muncul saat matahari cerah. Namun jika Anda menendang terlalu keras, akarnya akan membuat Anda tersandung, jadi berhati-hatilah!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000197', 'radical', '音', 'sound', 11, 7, 'Radikal ini sama dengan kanji. Artinya <radikal>suara</radikal>.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000198', 'radical', '少', 'few', 11, 8, 'Radikal ini sama dengan kanji. Artinya sedikit.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000199', 'radical', '単', 'simple', 11, 9, 'Ada sesuatu yang tumbuh di sawah ini dan ada salib yang menjaganya. Sawah ini dimiliki oleh keluarga sederhana yang hidup sederhana. Mereka menanam padi, berdoa kepada tuhan mereka, dan segala sesuatunya baik dan sederhana. Ahh, aku cemburu.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000201', 'radical', '早', 'early', 12, 0, 'Radikal ini sama dengan kanji. Artinya lebih awal.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000202', 'radical', '弟', 'younger-brother', 12, 1, 'Radikal ini sama dengan kanji. Artinya adik laki-laki.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000203', 'radical', '者', 'someone', 12, 2, 'Radikal ini sama dengan kanji. Itu berarti seseorang.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000204', 'radical', '亜', 'asia', 12, 3, 'Radikal ini terlihat seperti helikopter di darat. Atau petarung TIE dari atas (ke samping). Apa pun pilihannya, tidak apa-apa karena Anda tahu di mana helikopter dan pesawat tempur TIE dibuat: <radical>Asia</radical>! Saat ini sebagian besar pesawat dibuat di Asia, tahu?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000205', 'radical', '其', 'crab', 12, 4, 'Ini terlihat seperti kerang yang radikal tetapi lebih tajam dan gila. Makhluk bercangkang manakah yang mempunyai duri dan penjepit? Kepiting yang perkasa!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000206', 'radical', '廴', 'yoga', 12, 5, 'Ini terlihat seperti seseorang yang mengambil langkah besar dan meregangkan tubuhnya. Apakah itu terdengar seperti sesuatu yang Anda tahu? Seharusnya begitu, karena itulah yang Anda lakukan dalam <radical>yoga</radical>. Regangkan kaki dan lengan Anda sampai Anda terlihat radikal. Besar! Anda sedang melakukan yoga sekarang!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000207', 'radical', '示', 'jackhammer', 12, 6, 'Apakah Anda melihat pegangan di atas dan duri di bawah? Itu benar-benar hebat. Bagaimana Anda bisa mengetahuinya? Dua garis diagonal di samping menunjukkan gerakan jackhammer naik dan turun dengan sangat cepat, melakukan apa yang dilakukan jackhammers. BBBHHRZHHHHRHHRZHZHHZH JUJUJUJUJU.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000208', 'radical', '免', 'excuse', 12, 7, 'Radikal ini terdiri dari beberapa kaki yang membawa matahari keluar dari penjara. Kaki itu milikmu. Namun, ketika polisi menghentikan Anda, apa <radikal>alasan</radikal> Anda? Buatlah satu dan ucapkan dengan lantang, dimulai dengan, "Alasan saya adalah..."', NULL, NULL),
  ('00000000-0000-4000-8000-000000000209', 'radical', '非', 'criminal', 17, 0, 'Anda pikir Anda melihat beberapa kaki di balik jeruji itu. Siapa yang dipenjara? Hanya penjahat. Penjahat ini cukup tinggi, karena Anda hanya melihat kakinya di belakang sana.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000215', 'radical', '尺', 'shrimp', 13, 0, 'Radikal ini memiliki kepala kecil dan beberapa kaki udang yang mencuat keluar. Itu karena itu adalah <radikal>udang</radikal>!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000221', 'radical', '意', 'idea', 13, 1, 'Radikal ini sama dengan kanji. Artinya ide.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000222', 'radical', '坴', 'womb', 13, 2, 'Kaki muncul di antara dua gumpalan tanah. Ini adalah rahim versi bumi. Bayangkan seorang bayi mungil yang tumbuh di bawah tanah dan kemudian bertunas, dengan kaki pertama, ke dunia. Bayangkan berada di dalam rahim tanah ini. Ini hangat dan lembab. Anda merasa aman.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000223', 'radical', '丸', 'circle', 13, 3, 'Radikal ini sama dengan kanji. Artinya lingkaran.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000000904', 'kanji', '完', '完', 14, 14, 'Atap yang menjadi cikal bakal semua atap itu sempurna. Itu tinggi dan lebar sehingga bisa memuat dan melindungi semua orang. Dan dimensinya juga sempurna.', 'Atap yang sempurna ini dipesan oleh Jenghis Khan (かん). Kami mengumpulkan semua tukang kayu, pembuat rumah, dan pekerja konstruksi yang telah dia taklukkan dan menugaskan mereka untuk membuat atap pertama, tapi hanya jika mereka membuatnya benar-benar sempurna.', NULL),
  ('00000000-0000-4000-8000-000000000905', 'kanji', '希', '希', 14, 15, 'Ada harta karun di atas narwhal yang memakai handuk yang akan mengabulkan keinginan terbesar Anda.', 'Untuk membuka harta karun dan mendapatkan keinginanmu, kamu memerlukan kuncinya (き). Narwhal tahu di mana ia disembunyikan, jadi Anda harus meyakinkannya untuk memberi tahu Anda di mana kuncinya.', NULL),
  ('00000000-0000-4000-8000-000000000906', 'kanji', '念', '念', 14, 16, 'Jika Anda hidup di masa sekarang, kemungkinan besar hati Anda mengendalikan proses berpikir Anda. Anda tidak punya waktu untuk berpikir dengan otak Anda, Anda membutuhkan jawaban sekarang sehingga Anda menggunakan hati Anda untuk mengambil keputusan dan proses berpikir.', 'Anda hidup di masa sekarang dan membiarkan hati mengendalikan semua pikiran Anda. Mengapa kamu mengikuti kata hatimu? Anda menyadari bahwa Anda hanya memiliki satu 年 (ねん) untuk hidup, jadi Anda harus hidup untuk saat ini.', NULL),
  ('00000000-0000-4000-8000-000000000907', 'kanji', '折', '折', 14, 17, 'Jika jari Anda cukup kuat, Anda bisa mengambil kapak dan melipatnya menjadi dua. Namun hati-hati jangan sampai membengkokkannya terlalu jauh, atau Anda bisa mematahkannya!', 'Sayangnya, saat Anda melipat sumbu-sumbu ini menjadi dua, Anda menyadari bahwa sumbu-sumbu tersebut berpasangan (せつ), jadi terdapat dua kali lipat sumbu yang Anda kira. Sebagai kompensasinya, Anda juga mulai melipatnya menjadi beberapa set.', NULL),
  ('00000000-0000-4000-8000-000000000908', 'kanji', '望', '望', 14, 18, 'Menyebabkan kematian di setiap kesempatan, raja bulan duduk di dalam bulannya, bersiap untuk menyebabkan kematian pada apa pun yang terlihat. Kedengarannya sangat mirip Death Star dari film tertentu. Salah satunya adalah "Star Wars: A New Hope".', 'Nama A New Hope, seperti kita ketahui, berasal dari akhir di mana putra raja bulan mengirimkan bola bowling (ぼう) ke celah kecil itu dan menjatuhkannya ke langit.', NULL),
  ('00000000-0000-4000-8000-000000000909', 'kanji', '材', '材', 14, 19, 'Sebuah pohon bagi seorang jenius segera menjadi kayu. Mereka dapat melihat pohonnya dan melihat lebih banyak lagi: kemampuan untuk mengubahnya dari kayu menjadi material dan menggunakannya untuk jutaan hal berbeda.', 'Jenius ini tidak ingin menggunakan kayu untuk membangun rumah atau kursi, tidak, tidak, mereka akan menggunakan bahan-bahan ini untuk membuat gambang (ざい)! Instrumen yang paling sulit dibuat!!', NULL),
  ('00000000-0000-4000-8000-000000000910', 'kanji', '束', '束', 14, 20, 'Bundel radikal dan kanji bundelnya sama!', 'Anda harus selalu membundel kaus kaki Anda (そく). Jika tidak, ada kemungkinan 100% Anda akan kehilangan semua yang tersisa.', NULL),
  ('00000000-0000-4000-8000-000000000911', 'kanji', '松', '松', 14, 21, 'Saat memanjat pohon di depan umum, sebaiknya pilih pohon pinus. Pohon pinus memberikan cakupan paling luas, sehingga Anda dapat bersembunyi, bahkan di tempat umum.', 'Jika Anda terjatuh, seseorang telah meletakkan tikar (まつ) di sekitar pangkal pohon pinus. Dengan demikian, Anda akan mendarat di atas matras jika sesuatu yang tidak diinginkan terjadi.', NULL),
  ('00000000-0000-4000-8000-000000000912', 'kanji', '残', '残', 14, 22, 'Bar Yakuza hampir tidak ada. Sisanya bahkan tidak berada di Jepang.', 'Bar yakuza lainnya tidak ada di Jepang. Anehnya, semuanya ada di Zanzibar (ざん).', NULL),
  ('00000000-0000-4000-8000-000000000914', 'kanji', '的', '的', 14, 23, 'Seorang pria <radikal>kulit putih</radikal> melompat ke dalam <radikal>kolam</radikal> dengan <kanji>target</kanji> dicat di bagian bawah. Dia mengincar sasarannya.', 'Pria berkulit putih ini adalah seorang <reading>teknisi</reading> (<ja>てき</ja>) yang hebat sehingga dia memiliki peningkatan elektronik yang memastikan dia mencapai <kanji>target</kanji>. Menjadi seorang teknisi memiliki kelebihan.', NULL),
  ('00000000-0000-4000-8000-000000000915', 'kanji', '約', '約', 14, 24, 'Kamu mengikatkan benang di jarimu sebelum melompat ke dalam kolam untuk mengingatkan dirimu akan janji yang kamu buat kepada ibumu. Utas mewakili janji yang Anda buat untuk memotong rumput setelah Anda selesai berenang di kolam.', 'Setelah kamu keluar dari kolam, kamu menepati janji yang kamu buat kepada ibumu. Jadi, Anda menggunakan mesin pemotong rumput bertenaga yak (やく) dan memangkas rumput. Ya, mesin pemotong rumputmu ditarik oleh seekor yak. Ini sangat efisien.', NULL),
  ('00000000-0000-4000-8000-000000000916', 'kanji', '芸', '芸', 14, 25, 'Ada bunga palsu di kakimu dan awan palsu di atasmu karena kamu sedang berakting.', 'Anda harus melakukan beberapa akting yang melibatkan Anda menjadi gay (げい). Anda harus membayangkan adegan ini, apakah Anda gay dan itu bukan akting sebenarnya atau bukan.', NULL),
  ('00000000-0000-4000-8000-000000000917', 'kanji', '基', '基', 14, 26, 'Kepiting di tanah bisa menjadi fondasi yang bagus untuk pondok tepi laut. Letaknya tepat di tepi pantai, tempat semua kepiting menggali lubangnya di tanah. Namun seiring bertambahnya usia dan kematian, tubuh mereka membentuk dasar yang kuat. Cocok untuk pondasi bangunan seperti ini!', 'Ingat, fondasi yang baik adalah kunci (き) rumah yang bagus. Tidak, secara harfiah. Anda harus menggunakan sepotong pondasi untuk membuat kunci rumah Anda.', NULL),
  ('00000000-0000-4000-8000-000000000918', 'kanji', '性', '性', 14, 27, 'Setiap kehidupan memiliki jiwa, dan jiwa itu menentukan jenis kelamin Anda. Yang penting bukan tentang bagian tubuhmu, tapi apa yang ada di dalamnya.', 'Setelah kamu memutuskan jenis kelaminmu, Shougun (しょう) datang ke rumahmu, meletakkan pedangnya (せい) di bahumu, dan kemudian resmi! Itu ada di semua surat kabar, ada parade, dan semua orang menepuk punggung Anda karena Anda berhasil!', NULL),
  ('00000000-0000-4000-8000-000000000919', 'kanji', '技', '技', 14, 28, 'Anda bisa mencabangkan jari Anda. Itu keahlian khususmu. Jari-jari Anda bercabang menjadi jari-jari yang lebih kecil dan Anda dapat memegang benda dengan sangat baik. Anda bisa mengetik super duper dengan cepat. Dan Anda bisa memenangkan pertarungan apa pun. Ini adalah keterampilan yang Anda miliki berkat jari-jari Anda yang bercabang.', 'Sayangnya, keterampilan ini terlalu berat untuk ditangani oleh orang normal yang tidak memiliki keterampilan dan mereka mengeluarkan guillotine (ぎ). Saya kira mereka akan memotong jari-jari terampil Anda karena itu agak menakutkan.', NULL),
  ('00000000-0000-4000-8000-000000000920', 'kanji', '格', '格', 14, 29, 'Jika Anda mencium pohon, status Anda akan berubah menjadi, “Menjalin hubungan dengan pohon.”', 'Apa pun statusnya, Anda perlu memberi tahu pohon itu bagaimana perasaan Anda. Menjadi seekor ayam jantan (かく), lho, seekor ayam jantan, kamu ayam-a-doodle-lakukan perasaanmu yang sebenarnya pada pohon. Kamu sebenarnya hanya ingin berteman.', NULL),
  ('00000000-0000-4000-8000-000000000921', 'kanji', '能', '能', 14, 30, 'Anda menyimpan beberapa sendok pribadi di bulan dan itu memberi Anda kemampuan khusus. Itu adalah kemampuan untuk memprediksi masa depan! Sendok bulan mencerminkan pengetahuan tentang waktu dan ruang ke dalam otak Anda. Itu kemampuan yang keren!', 'Kemampuan meramal masa depan ini membuatmu terkenal dan sekarang semua orang tahu namamu: Nostradamus (のう)! Dan sekarang orang-orang mengetahui nama dan kemampuan khusus Anda, semua orang akan menyukai Anda!', NULL),
  ('00000000-0000-4000-8000-000000000922', 'kanji', '術', '術', 14, 31, 'Ini dia malaikat yang menjatuhkan diri di bahunya. Membawa tetes seperti itu adalah seni yang nyata. Itu membutuhkan teknik.', 'Malaikat sangat pandai dalam hal ini karena mereka dilatih dalam ninjutsu (じゅつ), atau "seni menjadi seorang ninja". Semua orang tahu bahwa ninja pandai membawa barang-barang saat bepergian!', NULL),
  ('00000000-0000-4000-8000-000000000924', 'kanji', '骨', '骨', 14, 32, 'Jika Anda berkumis dan dahi Anda terbentur bulan, kemungkinan besar tulang Anda akan patah. Oke, jadi tidak terlalu menjadi masalah jika Anda memiliki kumis, tetapi jika Anda melakukan perjalanan cukup cepat untuk sampai ke bulan, Anda pasti akan patah tulang jika menabraknya.', 'Luar angkasa dingin, dan jika Anda bepergian ke bulan, Anda akan memerlukan banyak mantel (こつ). Semua mantel ini akan membuat Anda tetap hangat, bahkan jika tulang dahi Anda patah.', NULL),
  ('00000000-0000-4000-8000-000000000925', 'kanji', '妥', '妥', 14, 33, 'Seorang wanita dengan cleat sedang berjalan di punggung seseorang, tapi dia tidak ingin menyakitinya. Dia harus sangat lembut. Cleatnya tajam dan runcing, dan tidak dirancang untuk berjalan mundur, jadi saat ini dia bersikap sangat lembut.', 'Sebenarnya, orang yang bersikap lembut padanya adalah ayahnya (だ). Tidak ada seorang pun yang ingin menyakiti ayahnya, terutama jika dia meminta Anda berjalan dengan lembut di punggungnya sebagai cara untuk memijatnya.', NULL),
  ('00000000-0000-4000-8000-000000000926', 'kanji', '雰', '雰', 14, 34, 'Sebagian hujan, sebagian lainnya. Saya membayangkan ini adalah apa yang orang-orang pikirkan tentang terbentuknya atmosfer ribuan tahun yang lalu.', 'Pembacaan kanji ini sebenarnya sama dengan 分s. Salah satu trik tentang kanji yang rumit adalah mereka sering kali membaca salah satu bagian yang dibuatnya. Dalam hal ini 分, itu keren.', NULL),
  ('00000000-0000-4000-8000-000000000927', 'kanji', '頑', '頑', 14, 35, 'Asal usul geoduck cukup keras kepala. Ras geoduck sangat keras kepala sehingga menolak berevolusi menjadi hewan yang masuk akal. Oleh karena itu, asal muasal geoduck adalah sifat keras kepala.', 'Anda tahu siapa lagi yang keras kepala? Gandhi (がん). Gandhi percaya pada perlawanan tanpa kekerasan dan dia cukup keras kepala dalam hal itu.', NULL),
  ('00000000-0000-4000-8000-000000000928', 'kanji', '寺', '寺', 15, 7, 'Radikal kuil dan kanji kuil sama persis! Cemerlang.', 'Seseorang meninggal. Anda bertanya bagaimana orang ini meninggal, orang yang dikuburkan di kuil. Pendeta/biksu mengatakan bahwa kejadian tersebut merupakan serangan teror (てら) yang tragis.', NULL),
  ('00000000-0000-4000-8000-000000000929', 'kanji', '岩', '岩', 15, 8, 'Batu gunung mungkin akan menjadi batu yang sangat besar. Kita berbicara tentang batu besar di sini.', 'Meskipun tidak menggunakan kanji yang sama, batu besar ini memiliki pembacaan yang sama dengan bagian pertama dari "Iwajima" yang terkenal (tempat terjadinya pertempuran besar dalam Perang Dunia II). Bayangkan sebuah batu besar. Sekarang bayangkan benda itu diceburkan ke laut untuk dijadikan sebuah pulau. Pulau apa itu? Itu Iwajima (ejaan historis Iwo Jima).', NULL),
  ('00000000-0000-4000-8000-000000000930', 'kanji', '帰', '帰', 15, 9, 'Sebuah <radical>pisau</radical> tertancap di <radical>dahi</radical> Wolverine, dan dia dililitkan <radical>handuk</radical> untuk menghentikan pendarahan, tapi dia benar-benar harus <kanji>kembali ke rumah</kanji>.', 'Wolverine ingin <kanji>pulang</kanji>, tapi dia tidak bisa menyetir sendiri karena ada pisau di dahinya dan banyak darah, jadi dia meminta temannya si <reading>ca</reading>r <reading>e</reading>lephant (<ja>かえ</ja>) untuk mengantarnya. Gajah mobil hanyalah seekor gajah mutan yang memiliki mobil di punggungnya.', NULL),
  ('00000000-0000-4000-8000-000000000931', 'kanji', '春', '春', 15, 10, 'Saat Anda melihat <radical>musim semi</radical> <radical>matahari</radical> Anda tahu bahwa ini akhirnya adalah musim <kanji>musim semi</kanji>.', 'Saat musim <kanji>musim semi</kanji> tiba, kamu pasti ingin tertawa: "<reading>HAR</reading> (<ja>はる</ja>) HAR HAR!" kamu berteriak.', NULL),
  ('00000000-0000-4000-8000-000000000932', 'kanji', '昼', '昼', 15, 11, '<radical>matahari</radikal> terbit dari <radikal>tanah</radikal>, dan di atasnya terdapat <radikal>udang</radikal> raksasa. Ia tidak melakukan apa pun kecuali setiap hari tepat pada <kanji>siang</kanji>, saat ia memberi tahu Anda waktunya. "Hei teman-teman, ini <kanji>siang</kanji>, mmk?"', 'Pada <kanji>siang</kanji>, udang juga mengenakan <reading>hak</reading> yang tinggi (<ja>ひる</ja>) untuk bersiap-siap menghadapi malam hari, di mana ia ingin memastikan udang tersebut terlihat bagus untuk udang lain yang ditemuinya nanti.', NULL),
  ('00000000-0000-4000-8000-000000000933', 'kanji', '晴', '晴', 15, 12, 'Matahari sudah terbit, langit berwarna biru, segalanya mulai cerah!', 'Sekarang semuanya mulai jelas, Anda tidak bisa menahan tawa. "Ha (は)! Ha ha ha!" kamu tertawa sampai ke langit. Sinar matahari terasa nyaman di wajah Anda, membuat Anda merasa bersemangat! Dan langit biru itu juga tidak terlalu buruk.', NULL),
  ('00000000-0000-4000-8000-000000000934', 'kanji', '秋', '秋', 15, 13, '<radical>Biji-bijian</radical> terlihat seperti <radical>berapi</radical> di <kanji>musim gugur</kanji>. Semuanya berubah menjadi merah, oranye, dan coklat, warna api. Menyenangkan juga membakar biji-bijian di musim gugur, karena cuaca semakin dingin.', 'Saat biji-bijian terbakar dan musim berganti ke musim gugur, bayangkan mereka berteriak kesakitan: "<reading>ACK</reading> (<ja>あき</ja>)!"', NULL),
  ('00000000-0000-4000-8000-000000000935', 'kanji', '計', '計', 15, 14, 'Jika Anda ingin <radical>mengatakan</radical> seberapa besar <radical>cross</radical>, Anda harus <kanji>mengukur</kanji> itu. Anda tidak dapat mengetahui ukuran suatu benda tanpa mengukurnya terlebih dahulu.', 'Anda perlu <kanji>mengukur</kanji> salib ini tetapi yang Anda miliki hanyalah <reading>ca</reading>ke (<ja>けい</ja>). Cukup bagus! Saya yakin semua kue memiliki ukuran yang sama persis, sehingga merupakan satuan ukuran yang dapat diandalkan.', NULL),
  ('00000000-0000-4000-8000-000000000936', 'kanji', '列', '列', 15, 15, 'Ambil pisau yakuzamu dan letakkan sejajar dengan yang lain.', 'Haruskah kita menempatkannya secara berurutan? Mari kita (れつ) menempatkannya dalam satu baris!', NULL),
  ('00000000-0000-4000-8000-000000000937', 'kanji', '区', '区', 15, 16, 'Sangkar berisi harta karun ini sebenarnya adalah peta distrik tempat harta karun itu berada.', 'Ada satu distrik yang Anda minati, dan itu adalah distrik cookie (く).', NULL),
  ('00000000-0000-4000-8000-000000000938', 'kanji', '坂', '坂', 15, 17, 'Ini anti kotoran. Kotoran tersebut semakin lama semakin menjadi bukan kotoran, membentuk... lereng! Sebenarnya apa itu udara di atas lereng tapi anti kotoran?', 'Hal-hal seperti ini tentang lereng perlu kamu ketahui jika ingin bermain sepak bola (さか). Sepak bola cukup intensif lereng. Anda benar-benar harus tahu cara membaca kotoran dan anti kotorannya agar benar-benar bagus.', NULL),
  ('00000000-0000-4000-8000-000000000939', 'kanji', '式', '式', 15, 18, 'Untuk membangun sebuah upacara yang utuh, Anda tidak bisa hanya mengada-ada di tempat. Itu bukanlah sebuah upacara. Sebuah upacara mempunyai masa lalu. Upacara dilakukan dengan cara tertentu karena memang selalu demikian. Singkatnya, untuk membangun sebuah upacara, Anda harus membuat ritualnya terlebih dahulu. Kemudian, ritual tersebut dapat dikonstruksikan menjadi upacara yang lebih besar dan mewah.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000001109', 'kanji', '産', '産', 20, 27, 'You stand on the Cliff of Life and give birth to a child. Oh no! You’re standing too close to the edge of the Cliff of Life! The baby falls off the cliff right after you give birth to it! In your despair, you throw all your property off the cliff too.', 'You give birth, and now this happens. Such bad luck. But wait! What''s that sound? Sleigh bells? Could it be?! It''s Santa-san (さん)! He caught your baby! And all your property.', NULL),
  ('00000000-0000-4000-8000-000000001110', 'kanji', '倒', '倒', 20, 28, 'Someone stabbed the leader mole with a knife to overthrow it. Now there is a new mole leader. Because that''s what happens when you overthrow someone—someone else needs to take over. In this case, a vengeful mole.', 'Where do leaders get overthrown the most? In とうきょう. Just think back in Japanese history, back when everyone was at war with one another. People were taking over and getting overthrown and then that guy gets overthrown and then THAT guy gets overthrown. Basically, it used to be hard to stay a leader in とうきょう.', NULL),
  ('00000000-0000-4000-8000-000000001111', 'kanji', '臭', '臭', 20, 29, 'Wash yourself with a big bar of soap if you''re stinking everything up.', 'You''re stinking up the room because you spent your day rolling in 草 (くさ). And based on this particular stench, I''d say an animal left something in that 草 too...', NULL),
  ('00000000-0000-4000-8000-000000001112', 'kanji', '厚', '厚', 20, 30, 'Hanging off the edge of a cliff is a sun worshipping child with a thick unibrow. Hanging off the cliff, the child cries at the sun for cursing him to this cruel fate. Even the thickness of his unibrow is not enough to give the child the strength to pull himself back up.', 'The child''s thick unibrow can''t wait any longer and gives up. It hops off the child''s face and says, "Hey dude, I''ll be at Sue''s (あつ). She''ll appreciate my thick, luxuriousness more than a weakling like you.', NULL),
  ('00000000-0000-4000-8000-000000001113', 'kanji', '妻', '妻', 20, 31, 'On the ground, holding a brush, is the woman you call your wife.', 'Your wife is drawing your cyborg (さい) on the ground. Oh no... now your wife is making kissy faces at the cyborg drawing.', NULL),
  ('00000000-0000-4000-8000-000000001114', 'kanji', '議', '議', 20, 32, 'What you say is righteousness, at least that''s what you believe. You keep talking and saying these things, and you don''t listen to anyone else''s words. This is your style of deliberation and discussion.', 'What are you in deliberation about? Whether or not to send some poor soul to the guillotine (ぎ). "I think he should go," you say. "I don''t think he should," says another. This deliberation is going nowhere...', NULL),
  ('00000000-0000-4000-8000-000000001115', 'kanji', '犯', '犯', 20, 33, 'In the animal kingdom, a snake is the most likely to commit a crime. Remember the Garden of Eden? The snake was the bad guy. Ever since then, snakes are the animal most known for committing crimes.', 'This snake has evaded the law for too long. It’s time for a true hero to put an end to its crime spree. Enter Han (はん) Solo. Han Solo is the only man strong and brave enough to put an end to this snake and his crime filled ways.', NULL),
  ('00000000-0000-4000-8000-000000001116', 'kanji', '罪', '罪', 20, 34, 'Put a net around a criminal to show their guilt. Criminals look like anyone else on the street, so you decide to tie them in nets to make sure people know who they''re dealing with.', 'The guilt shows on the criminal''s face. They smile, shrug, and pull a stolen xylophone (ざい) out of their back pocket.', NULL),
  ('00000000-0000-4000-8000-000000001117', 'kanji', '防', '防', 20, 35, 'If there is a building in the direction you want to go it will prevent you from going any further. Like, come on kid, you think you can just walk right through a building? Don''t make me laugh!', 'The building is preventing you from going the right direction, so you pull a bowling (ぼう) ball out of your bag, aim, and bowl the building over. The building, and all the ones around it, go tumbling down. But now the rubble is preventing you from going further.', NULL),
  ('00000000-0000-4000-8000-000000001118', 'kanji', '穴', '穴', 20, 36, 'The hole radical and the hole kanji are exactly the same! Spectacular!', 'Ana (あな) fell into a hole. Laugh at Ana and her unfortunate misfortune of having fallen into a hole like a ninny. Haha, Ana – you’re stupid and clumsy!', NULL),
  ('00000000-0000-4000-8000-000000001119', 'kanji', '論', '論', 20, 37, 'You say, throwing your hat on the ground in front of the bookshelf, "I have a theory!" All this reading and thinking has finally given you a wonderful idea, a theory you think might solve all of your problems!', '"What is your theory, Ron (ろん)?" asks Hermione. You''re Ron Weasley, and you just came up with a theory that you think will help you stop Voldemort.', NULL),
  ('00000000-0000-4000-8000-000000001120', 'kanji', '経', '経', 20, 38, 'Tying a thread to a tombstone each year will help you manage the passage of time. That way you’ll know how many years you pass through, since you’ll have one thread for each year to count.', 'Dealing with the passage of time can be tough, so after you tie the thread to the tombstone, each year you eat a piece of cake (けい). You already eat cake to mark the passage of time on your birthday, so why not here as well?', NULL),
  ('00000000-0000-4000-8000-000000001121', 'kanji', '笛', '笛', 19, 38, 'Is there a reason you''re in the bamboo grove? Why yes there is. It''s so you can get yourself some bamboo and make a flute out of it.', 'You cut down the bamboo and whittle a flute. You start playing a song. You know the reason why. An alien spacecraft comes flying down and drops a box full of alien tech (てき) in front of you.', NULL),
  ('00000000-0000-4000-8000-000000001122', 'kanji', '史', '史', 19, 39, 'The history radical and the history kanji are the same.', 'History was full of famous sheep (し). Sure there are people and stuff, but historical sheep are where it''s at. There''s the famous sheep samurai, the death sheep who works for the yakuza, just tons!', NULL),
  ('00000000-0000-4000-8000-000000001412', 'kanji', '詳', '詳', 17, 43, 'They say sheep are detailed creatures. I mean, I never thought sheep were very detailed, but that’s what they say.', 'The reason these sheep are so detailed is that they are trying to impress the Shougun (しょう). If they''re fancy enough, perhaps the Shougun won’t kill them for their meat and make their wool into clothing.', NULL),
  ('00000000-0000-4000-8000-000000001569', 'kanji', '劇', '劇', 17, 44, 'A tiger kills a pig with a knife in this new drama about the animal kingdom! The tiger and pig used to be friends when they were younger, but now they''re bitter enemies and the tiger just stabbed the pig right in the chest with a knife.', 'This drama is being put on by Gecki (げき), your childhood pet gecko. Gecki is playing all the parts, because as true drama fans know, one-gecko-shows are the highest form of art.', NULL),
  ('00000000-0000-4000-8000-000000001890', 'kanji', '僕', '僕', 12, 52, 'A leader of business? Ha! That''s me! That''s I!', 'You use the word I a lot. You say it so much, you just start referring to yourself with the french beaucoup (ぼく) for a lot. Because you love yourself a lot.', NULL),
  ('00000000-0000-4000-8000-000000002083', 'kanji', '丈', '丈', 15, 39, 'The height radical and the height kanji are the same!
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000003490', 'vocabulary', '返る', '返る', 11, 141, 'Mudah-mudahan Anda mengetahui kata 返す, yang artinya "mengembalikan" (misalnya, Anda melakukan tindakan langsung mengembalikan sesuatu). Sebaliknya, kata ini adalah versi di mana sesuatu baru saja kembali (dan Anda tidak melakukan tindakan pengembalian). Gunakan る untuk membantu Anda mengingat ini. る Kanguru dikembalikan padamu. Anda tidak melakukan pengembalian apa pun, itu terjadi begitu saja atau orang lain yang melakukannya. Itu sebabnya kata ini berarti dikembalikan.', 'The reading is the same as 返す, so as long as you know that you''ll be able to apply it here to learn the reading of this word as well.', NULL),
  ('00000000-0000-4000-8000-000000003497', 'vocabulary', '知り合い', '知り合い', 14, 42, 'Anda mungkin pernah melihat kata 知る dan 合う sekarang. Ini adalah seseorang yang Anda "kenal" karena Anda pernah "bertemu" sebelumnya, tapi itu saja. Anda belum begitu mengenal mereka dengan baik, Anda baru bertemu mereka beberapa kali sehingga Anda tahu siapa mereka. Orang ini adalah seorang kenalan.', 'The readings are that of 知る and 合う. So long as you know those words, you should be able to read this one too.', NULL),
  ('00000000-0000-4000-8000-000000003498', 'vocabulary', '乗り場', '乗り場', 11, 142, 'Mudah-mudahan Anda sudah melihat kata 乗る dan mengetahui artinya "berkendara". Jadi kata ini ada hubungannya dengan "lokasi berkendara". Ke mana Anda pergi untuk mendapatkan tumpangan ke suatu tempat? Kemungkinan besar, itu adalah halte bus atau tempat taksi.', 'This word uses the kun''yomi readings, which you''ve learned already. Also, use 乗る to help you to remember the reading for 乗り.', NULL),
  ('00000000-0000-4000-8000-000000003499', 'vocabulary', '使い方', '使い方', 11, 143, 'Semoga Anda sudah melihat kata <ja>使う</ja> sekarang. Jika pernah, Anda pasti tahu artinya "menggunakan". Jadi, <kanji>cara</kanji> untuk <kanji>menggunakan</kanji> sesuatu adalah <vocabulary>cara menggunakan</vocabulary> (alias <vocabulary>cara menggunakan</vocabulary>). Ini akan menjadi kata yang Anda lihat saat Anda melihat petunjuk cara menggunakan sesuatu.', 'Ini menggunakan bacaan kun''yomi dari vocab kata <ja>使う</ja> dan <ja>方</ja>. Jadi selama Anda setuju dengan itu, Anda bisa menerapkan pengetahuan itu di sini.', NULL),
  ('00000000-0000-4000-8000-000000003500', 'vocabulary', '仕事', '仕事', 11, 144, '"<kanji>melakukan</kanji> <kanji>tindakan</kanji>" Anda adalah hal-hal yang Anda lakukan. Apa yang Anda katakan ketika seseorang bertanya "apa yang Anda lakukan"? Anda memberi tahu mereka apa <vocabulary>pekerjaan</vocabulary> Anda.', 'Kata ini menggunakan bacaan on''yomi untuk <ja>仕</ja> dan bacaan kun''yomi untuk <ja>事</ja>. Harap dicatat bahwa <ja>事</ja> menggunakan bacaan <ja>こと</ja>, yang tidak Anda pelajari dengan kanji, tetapi Anda sudah menemukannya sekali atau dua kali sekarang, dan karena cara kerja rendaku, itu diubah menjadi <ja>ごと</ja> bersuara.', NULL),
  ('00000000-0000-4000-8000-000000003502', 'vocabulary', '負け犬', '負け犬', 11, 145, 'Mudah-mudahan Anda sudah menemukan 負ける sekarang, yang artinya "kalah". Jadi, Anda dapat mengetahui bahwa kata ini berarti "anjing yang kalah". Memanggil seseorang sebagai anjing tidaklah baik, jadi Anda mungkin hanya menyebut mereka pecundang.', 'The readings are kun''yomi, but you should be familiar with 負ける and of course 犬 well enough to learn the reading here.', NULL),
  ('00000000-0000-4000-8000-000000003503', 'vocabulary', '待ちぼうけ', '待ちぼうけ', 14, 43, 'Dengan <vocabulary>待ち</vocabulary> Anda tahu bahwa Anda sedang menunggu, tapi apa itu <vocabulary>ぼうけ</vocabulary>? Ternyata itu versi panjang dari <ja>ボケ</ja> yang artinya idiot. Pada dasarnya, dalam hal ini Anda adalah seorang idiot yang menunggu. Mengapa? karena kamu <vocabulary>berdiri</vocabulary>.', 'Pembacaan <ja>待ち</ja> berasal langsung dari <ja>待つ</ja>. Anda sudah tahu latihannya sekarang.', NULL),
  ('00000000-0000-4000-8000-000000003504', 'vocabulary', '勝ち', '勝ち', 11, 146, 'Mudah-mudahan Anda sudah melihat 勝つ sekarang, yang artinya "menang". Ini adalah versi nominalnya. Jadi, apa versi kata benda dari "menang?" Itu adalah kemenangan atau kemenangan.', 'The reading comes from 勝つ. So as long as you have some understanding of that reading, you should be able to read this one as well.', NULL),
  ('00000000-0000-4000-8000-000000003505', 'vocabulary', '決定する', '決定する', 11, 147, 'Sebuah 決定 adalah sebuah "keputusan". Jadi, ketika kamu menambahkan する ke dalamnya, kamu menjadikannya kata kerja, artinya kata ini berarti memutuskan.', 'The reading is the same as 決定 with する added. Make sure you know 決定 and you''ll know this word as well.', NULL),
  ('00000000-0000-4000-8000-000000003507', 'vocabulary', '苦しむ', '苦しむ', 11, 148, 'Anda sudah diperkenalkan dengan kata 苦しい. Kata itu berarti menyakitkan, atau menyiksa. Jadi, jika Anda mengubahnya menjadi kata kerja, Anda harus menderita atau berjuang.', 'The reading comes from 苦しい, so as long as you''re on top of that word, this word should be readable for you as well.', NULL),
  ('00000000-0000-4000-8000-000000003508', 'vocabulary', '気付く', '気付く', 11, 149, 'Saat kamu melampirkan energimu (bayangkan seseorang tiba-tiba menatap sesuatu, menempelkan energinya padanya), kamu telah memperhatikan atau menyadari sesuatu. Karena itulah kata ini berarti menyadari atau memperhatikan. 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000003704', 'vocabulary', '残り', '残り', 14, 97, 'Ini memiliki arti yang sama dengan kanji.り kecil yang dilempar ke sana hanyalah sedikit sisa yang menempel di ujung kanji. Tidak perlu memperhatikan hal itu.', 'Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun''yomi reading. You didn''t learn that reading with this kanji, so here''s a mnemonic to help you: You''re waiting inside. The remainder of your forces are out there, fighting. You don''t know who will survive... or if they even will. You have a secret knock (のこ), though, that you use to find out if it''s one of the remaining forces outside or the enemy, broken through. You hear a knock. What is it? Is it your men or theirs? Imagine it out, focusing on the knock conversation that happens between you and the remainder.', NULL),
  ('00000000-0000-4000-8000-000000003705', 'vocabulary', '残る', '残る', 14, 98, 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri berarti sisa, jadi versi vocab verbanya adalah "sisa". Mari kita buat hal ini terdengar lebih baik: tetap tertinggal.', 'Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun''yomi reading. You didn''t learn that reading with this kanji, so here''s a mnemonic to help you: You decide to remain behind. Everyone else leaves, and you think you''re alone. Then, someone knocks (のこ) on the door. Your heart jumps in your throat. They knock again.', NULL),
  ('00000000-0000-4000-8000-000000003706', 'vocabulary', '残業', '残業', 14, 99, 'Sisa waktu Anda bekerja di bisnis lama adalah waktu ekstra Anda bekerja (di atas jam kerja normal). Ini lembur!', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003710', 'vocabulary', '料理', '料理', 14, 100, 'Ada <kanji>alasan</kanji> untuk <kanji>biaya</kanji> ini yang harus Anda bayar untuk masuk ke sini. Kami <vocabulary>memasak</vocabulary> <vocabulary>masakan</vocabulary> untuk Anda makan sambil menonton pertunjukan. Jika kami tidak memasak <vocabulary>hidangan</vocabulary> untuk Anda, kami mungkin tidak akan membebankan biaya ini kepada Anda!', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003711', 'vocabulary', '〜的', '〜的', 14, 101, 'Saya khawatir ini adalah kata yang aneh. Anda harus menanggungnya. Ini, ketika ditambahkan ke sebuah kata, seperti menambahkan "-al" ke sebuah kata (atau -seperti ke sebuah kata). Misalnya, tambahkan ke <ja>日本</ja> (Jepang) dan Anda akan mendapatkan "Seperti Jepang", yang hasilnya adalah "Sangat Jepang". Ini adalah jenis modifikasi kata yang aneh dan sangat bergantung pada situasi masing-masing, meskipun <reading>-al</reading> dan <reading>-like</reading> sering kali berfungsi dengan baik. Untuk saat ini, ketahuilah bahwa kata ini memiliki arti seperti ini. Kami akan mulai menerapkannya pada berbagai kata di masa depan, perlahan tapi pasti.', 'Pembacaannya sama dengan yang kamu pelajari dengan kanji, mungkin karena ini biasanya ditambahkan ke kata lain, membuatnya berperilaku seperti jukugo.', NULL),
  ('00000000-0000-4000-8000-000000003712', 'vocabulary', '日本的', '日本的', 14, 102, 'Hal-hal yang <kanji>ditargetkan</kanji>dianggap sebagai <vocabulary>Jepang</vocabulary> lebih dari sekedar bahasa Jepang, mereka <vocabulary>sangat Jepang</vocabulary>. Kata ini mungkin sulit dipahami pada awalnya, namun ada banyak hal yang dianggap hanya bahasa Jepang oleh orang Jepang. Teori-teori ini berkisar dari yang masuk akal hingga yang menggelikan, namun bagaimanapun juga, Anda akan melihatnya digambarkan sebagai <ja>日本的</ja>.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya. Akan membantu jika Anda juga mengetahui cara membaca <ja>日本</ja>.', NULL),
  ('00000000-0000-4000-8000-000000003713', 'vocabulary', '目的', '目的', 14, 103, 'Ketika <kanji>mata</kanji> Anda berada pada <kanji>target</kanji> Anda mengetahui <vocabulary>tujuan</vocabulary> Anda. Anda juga memperhatikan <vocabulary>tujuan</vocabulary> (bagaimanapun juga, itulah targetnya!).', 'Pembacaannya adalah pembacaan <ja>目</ja> yang tidak normal. Anda telah melihat bacaan ini dengan <ja>目標</ja> dan <ja>目次</ja>, jadi semoga saja saat ini tidak terlalu sulit. Bayangkan saja memberi tahu seseorang <ja>目的</ja> Anda, hanya untuk membuat mereka tertawa di depan Anda dan mulai <read>mengejek</reading>mengejek <ja>もく</ja> Anda karenanya. Sekarang Anda tidak begitu yakin apakah tujuan Anda akan berhasil.', NULL),
  ('00000000-0000-4000-8000-000000003718', 'vocabulary', '予約', '予約', 14, 104, 'Janji sebelumnya adalah janji yang telah Anda buat sebelumnya. Ini adalah reservasi atau janji temu. Masuk akal, bukan?', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003719', 'vocabulary', '約', '約', 14, 105, 'Kanji artinya janji, namun arti kata ini adalah tentang yang sedikit berbeda. Coba pikirkan tentang janji. Ketika Anda menjanjikan sesuatu, Anda benar-benar harus menepatinya... tetapi hanya sebanyak yang Anda perlukan agar orang lain bahagia. Seseorang meminta anak anjing untuk Natal, dan Anda memberi mereka boneka anak anjing. Ini kira-kira janji yang Anda buat. Cukup dekat. *mengedipkan mata*', 'The reading is the same as the one you learned with the kanji. See? I promised this one would be easy and it was.', NULL),
  ('00000000-0000-4000-8000-000000003720', 'vocabulary', '約束する', '約束する', 16, 40, '約束 adalah sebuah “janji.” Jadi ketika Anda menambahkan する ke dalamnya, Anda menjadikannya kata kerja, artinya berjanji. Sekarang berjanjilah Anda akan mengingatnya!', 'The reading is the same as 約束 with する added. Make sure you know 約束 and you''ll know this word as well.', NULL),
  ('00000000-0000-4000-8000-000000003721', 'vocabulary', '才能', '才能', 14, 106, 'Dia yang memiliki kemampuan jenius mempunyai bakat yang cukup besar.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003722', 'vocabulary', '能力', '能力', 14, 107, 'Kekuatan kemampuan Anda adalah apa yang dapat Anda lakukan. Ini adalah kemampuan Anda. Itu juga merupakan kemampuan Anda.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003723', 'vocabulary', '芸能界', '芸能界', 14, 108, 'Dunia kemampuan akting adalah dunia bisnis pertunjukan atau dengan kata lain industri hiburan.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003724', 'vocabulary', '芸人', '芸人', 14, 109, 'Seseorang yang melakukan akting lucu adalah seorang komedian. Anda mungkin mengira dia adalah aktor, tetapi biasanya dia adalah seorang komedian. Anggap saja mereka lebih seperti seorang pemain!', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003725', 'vocabulary', '芸者', '芸者', 14, 110, 'Anda akan berpikir bahwa seseorang yang berakting adalah seorang aktor atau semacamnya... tapi pikirkan tentang bacaan kanji ini. Apa itu? Apakah Anda mengenali kata itu? Itu geisha.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003726', 'vocabulary', '芸術', '芸術', 14, 111, 'Seni akting adalah seni terhebat dari semuanya. Dulu, seni akting hanyalah satu-satunya seni, itulah sebabnya seni akting hanyalah seni itu sendiri. Faktanya, itu adalah seni.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003727', 'vocabulary', '美術', '美術', 14, 112, 'Seni kecantikan adalah seni rupa, atau sekadar seni.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003728', 'vocabulary', '骨', '骨', 14, 113, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Since this word is made up of a single kanji, it should use the kun''yomi reading. When learning the kanji, you didn''t learn that reading, so here''s a mnemonic to help you with this word: Take a look at your own bones. They have been upgraded with special technology, allowing you to hone (ほね) in on targets, then shoot your bones at them. Go ahead and imagine yourself using this crazy new bone technology. Wolverine is jealous.', NULL),
  ('00000000-0000-4000-8000-000000003729', 'vocabulary', '仏', '仏', 15, 46, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Since this word is made up of a single kanji, it should use the kun''yomi reading. When learning the kanji, you didn''t learn that reading, so here''s a mnemonic to help you with this word: You go up to Buddha. You want to rub his head for good luck, because that''s what you hear is good to do. Right before you touch him, he backs off and says, "Whoa! I''m hot, okay?" (ほとけ). You touch him and it burns your hand clean off. 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000003915', 'vocabulary', '不完全', '不完全', 16, 123, 'Anda tahu bahwa 完全 berarti "lengkap" atau "sempurna". Jadi, yang tidak “lengkap” atau “sempurna” adalah sesuatu yang tidak lengkap atau tidak sempurna.', 'This is a jukugo word, which usually means on''yomi readings from the kanji. If you know the readings of your kanji you''ll know how to read this as well. It also will help if you can read 完全.', NULL),
  ('00000000-0000-4000-8000-000000003916', 'vocabulary', '美術館', '美術館', 16, 124, 'Anda tahu 美術 adalah seni rupa. Lalu apa yang dimaksud dengan bangunan publik yang memuat seni rupa tersebut? Itu adalah museum.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003917', 'vocabulary', '折り紙', '折り紙', 16, 125, 'Anda tahu bahwa 折る berarti "melipat", lalu bagaimana dengan "melipat kertas"? Pernah mendengar sesuatu yang melibatkan banyak pelipatan kertas dalam bahasa Jepang? Kemungkinan besar Anda pernah mengalaminya. Inilah origami alias seni melipat kertas.', 'The reading comes from 折る and the vocab word 紙. As long as you know those you should be able to read this. Also, you probably already know this reading because it''s an English word, too.', NULL),
  ('00000000-0000-4000-8000-000000003919', 'vocabulary', '希望', '希望', 14, 130, 'Harapan dan keinginan Anda terkandung dalam kosakata ini. Jadi, apa arti kata ini? Itu adalah harapan dan harapan. Keduanya akan berhasil.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003920', 'vocabulary', '希望する', '希望する', 16, 126, 'Anda tahu bahwa 希望 adalah "keinginan" atau "harapan". Jadi, ketika Anda "melakukan sebuah keinginan" atau "melakukan sebuah harapan". Ketika Anda melakukan itu, itu berarti meminta atau berharap.', 'The reading comes from 希望. It''s also the on''yomi jukugo reading as well, if that helps any.', NULL),
  ('00000000-0000-4000-8000-000000003921', 'vocabulary', '技術', '技術', 16, 127, 'Anda pernah melihat 技 sebagai kosakata yang berarti "teknik". Ini semacam menggunakan makna itu. Jadi, suatu teknik seni tetaplah seni, tapi itu juga keahlian Anda, teknik Anda.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003922', 'vocabulary', '妥協する', '妥協する', 16, 128, 'Anda tahu bahwa 妥協 berarti kompromi. Jadi, apa yang terjadi jika Anda menjadikannya kata kerja? Ini menjadi kompromi.', 'The reading is the same as the vocab word 妥協, so if you know that you should be good (also, just the reading of the kanji works too).', NULL),
  ('00000000-0000-4000-8000-000000003923', 'vocabulary', '妥協', '妥協', 14, 131, 'Ketika Anda memiliki kerja sama yang lembut, tidak ada orang yang bisa melakukan apa yang mereka inginkan. Anda dengan sangat hati-hati mendekati titik tengah, mencapai kompromi. (Suka atau tidak.)', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003925', 'vocabulary', '要求する', '要求する', 12, 159, 'Mudah-mudahan Anda tahu bahwa 要求 adalah sebuah permintaan. Ketika Anda menjadikannya kata kerja, itu menjadi menuntut sesuatu.', 'The reading is just the vocab word 要求. It''s also the regular on''yomi jukugo reading.', NULL),
  ('00000000-0000-4000-8000-000000003926', 'vocabulary', '消化', '消化', 12, 160, 'Sesuatu apa yang pertama-tama akan memadamkan sesuatu dan kemudian mengubahnya? Satu hal yang terpikir olehku adalah tubuhmu. Dibutuhkan dalam makanan, memadamkannya di perut Anda, lalu mengubahnya menjadi sesuatu yang dapat digunakan tubuh Anda (dan kemudian dikeluarkan). Itu sebabnya proses “pemadaman-perubahan” ini terjadi pada pencernaan Anda.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000003927', 'vocabulary', '消化不良', '消化不良', 14, 132, 'Mudah-mudahan Anda sudah melihat 消化 sekarang dan tahu bahwa artinya "pencernaan". Jika Anda mengetahuinya, maka Anda dapat melihat bahwa “pencernaannya” kurang baik. Ketika pencernaan Anda tidak baik, apa yang Anda miliki? Gangguan pencernaan. Permisi, saya harus lari ke kamar kecil...', 'This is a jukugo word, which usually means on''yomi readings from the kanji. If you know the readings of your kanji you''ll know how to read this as well. Knowing 消化 and 不良 will help as well.', NULL),
  ('00000000-0000-4000-8000-000000003928', 'vocabulary', '不合格', '不合格', 16, 129, 'Anda tahu bahwa 合格する berarti "lulus ujian", lalu apa kebalikannya? Gagal dalam ujian atau kegagalan.', 'If you know the reading for 合格, all you have to do is add 不 to it! You''ve learned all these readings, yay!', NULL),
  ('00000000-0000-4000-8000-000000003929', 'vocabulary', '卒業する', '卒業する', 16, 130, 'Anda tahu bahwa 卒業 adalah "wisuda". Jadikan itu kata kerja, dan Anda harus lulus.', 'The reading is just the same as the vocab word 卒業.', NULL),
  ('00000000-0000-4000-8000-000000003930', 'vocabulary', '残す', '残す', 16, 131, 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti sisa, tapi Anda tidak bisa benar-benar "meninggalkannya". Hal serupa apa yang masuk akal? Bagaimana kalau meninggalkan. Ini adalah saat Anda benar-benar melakukan tindakan meninggalkan juga. Misalnya saja, kamu makan sedikit dan nasimu tertinggal karena kamu adalah anak yang nakal. Anda dapat mengingat ini karena す. Setiap kali kamu meninggalkan makanan, ibumu akan menuntutmu, karena dia adalah ibu yang buruk. Bayangkan ini.', 'The reading for this word can come from level 14 item 残る. Associate the two in your mind and you''ll be able to read both.', NULL),
  ('00000000-0000-4000-8000-000000003931', 'vocabulary', '固める', '固める', 16, 132, 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya keras jadi versi vocab verbanya? Untuk membuat sesuatu menjadi sulit. Namun, Anda perlu membedakannya dengan 固まる, yang berarti "mengeras" (pengerasan terjadi dengan sendirinya). Kata ini berarti "membuat sesuatu menjadi keras", karena Andalah yang melakukan pengerasan tersebut. Anda dapat mengingat ini karena Anda ingin membuat sesuatu menjadi keras. Dan untuk melakukan itu, Anda mengirim "surat" khusus (める) ke hal yang ingin Anda buat menjadi sulit, dan surat ini melakukannya untuk Anda.', 'Since the reading for 固 (かた) is different than the one you learned with the kanji, here''s a mnemonic to help you:
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000004118', 'vocabulary', '焼き肉', '焼き肉', 18, 103, 'Mmmmm, enak! Ambil sedikit daging dan masak. Kemudian Anda memiliki daging panggang atau yakiniku. Jika Anda pergi ke Jepang, carilah tempat 焼肉 (arti/bacaan yang sama). Mereka enak, setidaknya jika Anda menyukai daging.', '焼き uses the reading you learned with the kanji. 肉 does too. Put them on the grill and enjoy!', NULL),
  ('00000000-0000-4000-8000-000000004119', 'vocabulary', '夕焼け', '夕焼け', 18, 104, 'Ketika sore hari terik matahari, matahari terbenam, mendekati cakrawala dan bumi. Inilah matahari terbenam, atau lebih spesifiknya, cahaya senja yang bisa Anda lihat saat matahari terbenam.', 'The readings are the kun''yomi vocab readings. Combine 夕 and 焼け (you learned the reading via the kanji) and you''ll have ゆうやけ.', NULL),
  ('00000000-0000-4000-8000-000000004120', 'vocabulary', '煙', '煙', 18, 105, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Since this word is made up of a single kanji, it should use the kun''yomi reading. When learning the kanji, you didn''t learn that reading, so here''s a mnemonic to help you with this word: You''re standing around a smoke machine. It''s billowing up smoke. Strangely, your buddy Bill Murray is here too. For some reason, he loves the smoke, and he puts his head in it, breathing it in deeply until he goes into a coughing fit. You decide it''s time to stop him. "Kay, Murray (けむり), it''s time to stop that," you say.', NULL),
  ('00000000-0000-4000-8000-000000004121', 'vocabulary', '黒煙', '黒煙', 18, 106, 'Asap hitam adalah asap hitam. Itu juga sesuatu yang harus Anda hindari jika bisa.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004122', 'vocabulary', '祈る', '祈る', 18, 107, 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya berdoa dan kata kerja ini bersifat transitif, jadi artinya mendoakan.', 'Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun''yomi reading. You didn''t learn that reading with this kanji, so here''s a mnemonic to help you: "You gotta pray for Christmas presents if you want Santa to bring you some!" "I know (いの), I know," you reply as you begin to pray for presents. You should say this out loud to remember it better.', NULL),
  ('00000000-0000-4000-8000-000000004123', 'vocabulary', '祈念', '祈念', 18, 108, 'Pikiranmu adalah doa. Pikiran berdoa ini adalah doa.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004124', 'vocabulary', '祈願', '祈願', 18, 109, 'Anda berdoa dan meminta. Ini adalah doamu.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004125', 'vocabulary', '禁煙', '禁煙', 18, 110, 'Jika merokok dilarang, Anda mungkin sebaiknya tidak merokok. Alias ​​dilarang merokok, oke?', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004126', 'vocabulary', '禁止', '禁止', 18, 111, 'Berhenti! Itu larangan (dilarang)! Ketika ada sesuatu yang dilarang dan Anda terpaksa berhenti, maka hal itu jelas haram. Jika Anda melihat ini, Anda mungkin sebaiknya tidak melakukan hal yang diperintahkan untuk tidak Anda lakukan.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004127', 'vocabulary', '禅寺', '禅寺', 18, 112, 'Kuil zen memang seperti namanya, kuil zen. Kedengarannya bagus.', 'The reading is the two words 禅 and 寺 put together. The てら gets changed to でら, though.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000004329', 'vocabulary', '論理', '論理', 20, 113, 'Dengan menggunakan teori dan nalar, Anda termasuk orang yang banyak menggunakan logika. Bayangkan orang seperti ini, saya yakin Anda mengenal setidaknya satu orang.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004330', 'vocabulary', '会議', '会議', 20, 114, 'Tempat berkumpulnya orang-orang dan melakukan musyawarah. Kedengarannya membosankan, tapi juga terdengar seperti semacam pertemuan atau konferensi.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004331', 'vocabulary', '議論', '議論', 20, 115, 'Ada banyak pertimbangan dan pertukaran teori ketika Anda mencoba menyajikan argumen. Tentu saja itu sangat bagus. Banyak pemikiran dan hal-hal lain, Anda tahu? Makanya ada musyawarah dan teori, bukan sekadar teriak-teriak. "Argumen" semacam itu.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004332', 'vocabulary', '不思議', '不思議', 20, 116, 'Ini bukanlah apa yang Anda pikir akan terjadi selama pertimbangan Anda. Anda pikir itu akan sangat normal. Sebaliknya, justru sebaliknya. Penuh keajaiban dan misteri. Luar biasa', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004333', 'vocabulary', '防止', '防止', 20, 117, 'Mencegah dan menghentikan seseorang melakukan sesuatu adalah pencegahan. Ada baiknya melakukan pencegahan daripada membiarkan hal buruk terjadi.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004334', 'vocabulary', '防ぐ', '防ぐ', 20, 118, 'Anda sedang melakukan pencegahan. Ketika Anda mencegah sesuatu, apa yang sebenarnya Anda lakukan? Anda mencoba mempertahankan diri agar tidak terjadi sesuatu. Itu sebabnya kata kerja ini sedikit aneh dan berarti membela atau melindungi. Bisa juga untuk mencegah, tapi pastikan Anda memikirkannya seperti sedang membela sesuatu dengan pencegahan Anda.', 'Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun''yomi reading. You didn''t learn that reading with this kanji, so here''s a mnemonic to help you: You want to defend against the enemy? You should probably put out that fuse (ふせ) attached to that giant bomb first then.', NULL),
  ('00000000-0000-4000-8000-000000004335', 'vocabulary', '防水', '防水', 20, 119, 'Sesuatu yang menghalangi air bersifat kedap air dan kedap air. Waktunya mandi pakai 防水 ponselku...', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004336', 'vocabulary', '防火', '防火', 20, 120, 'Mencoba mencegah kebakaran? Lebih baik melakukan pencegahan kebakaran.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004337', 'vocabulary', '予防', '予防', 20, 121, 'Mencegah terlebih dahulu tetaplah pencegahan.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004338', 'vocabulary', '困難', '困難', 20, 122, 'Anda tertekan dan itu sulit. Ini cukup berat dan kesulitan yang Anda rasakan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000004339', 'vocabulary', '非難', '非難', 20, 123, 'Ketidakadilan yang sulit diterima dari seseorang adalah kritik. Ugh, sungguh menyakitkan untuk dikritik! Sangat sulit, dan selain itu, ini adalah ketidakadilan, karena saya sempurna!', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004340', 'vocabulary', '難しい', '難しい', 20, 124, 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat dari sulit? Itu juga sulit.', 'Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun''yomi reading. You didn''t learn that reading with this kanji, so here''s a mnemonic to help you: It''s awfully difficult to load a cow into your Moo-zooka (むずか). Click. Boom!', NULL),
  ('00000000-0000-4000-8000-000000004341', 'vocabulary', '地震', '地震', 20, 125, 'Gempa bumi hanyalah cara lain untuk mengatakan gempa bumi.', 'This is a jukugo word, which usually means on''yomi readings from the kanji. If you know the readings of your kanji you''ll know how to read this as well. Notice that 地 is read as じ instead of ち. You''ve seen this happen a few times before, so just try to remember that this is the case here.', NULL),
  ('00000000-0000-4000-8000-000000004342', 'vocabulary', '震度', '震度', 20, 126, 'Derajat gempa adalah cara Anda mengukur gempa.震度 adalah intensitas gempa, besaran gempa AKA, intensitas seismik, atau skala seismik.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004343', 'vocabulary', '余震', '余震', 20, 127, 'Gempa surplus (itu tambahan!) adalah gempa yang terjadi setelah gempa utama (non-surplus). Itu adalah gempa susulan.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004344', 'vocabulary', '人類学', '人類学', 20, 128, 'Studi tentang umat manusia (人類) dikenal sebagai antropologi.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000004345', 'vocabulary', '飛ぶ', '飛ぶ', 20, 129, 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya terbang jadi versi vocab verbanya adalah terbang.', 'When you try to fly, the main thing holding you back is your toe (と). It''s like forty pounds and holds you down.', NULL),
  ('00000000-0000-4000-8000-000000004346', 'vocabulary', '果たして', '果たして', 19, 129, 'Jadi ini tidak terlalu masuk akal dari segi kanji dan kata-katanya, tapi memang begitulah adanya. Mari kita mengingatnya seperti ini:
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000008700', 'vocabulary', '合図', '合図', 14, 150, 'Diagram yang dilihat semua orang bersama-sama adalah sebuah sinyal atau tanda.', 'This word uses the kun''yomi reading for 合 and the on''yomi reading for 図. You know them both now, so you should be able to read this too!', NULL),
